MAP_SCHOOLS.forEach(s=>{if(s.prov&&s.canton){if(!MAP_CANTONES[s.prov])MAP_CANTONES[s.prov]=[];if(!MAP_CANTONES[s.prov].includes(s.canton))MAP_CANTONES[s.prov].push(s.canton);}});
let _mapCreated=false;
let _mapObj=null;
let _layerGroups={};
let _activeProvinces=new Set(MAP_PROVINCES);
let _activeCanton='';

/* ── Colores por estado de entrega ── */
const ESTADO_COLORS={entregada:'#1F9D55',en_ruta:'#F47C20',pendiente:'#9AA4B8',problema:'#EF4444'};
const ESTADO_LABELS={entregada:'✅ Entregada',en_ruta:'🚚 En ruta',pendiente:'⏳ Pendiente',problema:'⚠️ Problema'};

function initSICMap(){
  const el=document.getElementById('map');
  if(!el)return;
  if(!_mapCreated){
    _mapCreated=true;
    _mapObj=L.map('map',{center:[-1.85,-78.85],zoom:8,zoomControl:true});
    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{
      attribution:'© OpenStreetMap',maxZoom:19
    }).addTo(_mapObj);
  }
  renderMapMarkers();
}


/* Actualiza los contadores junto a cada filtro */
function updateFilterCounts(){
  const coordMap={};
  MAP_SCHOOLS.forEach(s=>{coordMap[s.amie]=s;});

  // Base source: SCHOOLS (Excel) si está cargado, MAP_SCHOOLS si no
  const useSchools=SCHOOLS.length>0;

  // Counters
  const cEst={entregada:0,en_ruta:0,pendiente:0,problema:0};
  const cReg={SIERRA:0,COSTA:0};
  const cAcc={Terrestre:0,Fluvial:0,'Aérea':0};
  const cZin={Urbana:0,Rural:0};

  if(useSchools){
    SCHOOLS.forEach(s=>{
      const ref=coordMap[s.amie];
      // Count even if no MAP_SCHOOLS match (use Excel data)
      const est=s.estado||'pendiente';
      if(cEst[est]!==undefined)cEst[est]++;
      const reg=(ref&&ref.reg)||s.reg||'';
      if(cReg[reg]!==undefined)cReg[reg]++;
      const acc=s.acceso||(ref&&ref.acc)||'Terrestre';
      if(cAcc[acc]!==undefined)cAcc[acc]++;
      const zon=(ref&&ref.zona)||s.zonaInec||'';
      if(cZin[zon]!==undefined)cZin[zon]++;
    });
  } else {
    MAP_SCHOOLS.forEach(s=>{
      if(cReg[s.reg]!==undefined)cReg[s.reg]++;
      if(cAcc[s.acc]!==undefined)cAcc[s.acc]++;
      if(cZin[s.zona]!==undefined)cZin[s.zona]++;
    });
  }

  // Render counts
  const set=(id,v)=>{const el=document.getElementById(id);if(el)el.textContent=v>0?v.toLocaleString('es-EC'):'—';};
  set('cnt-est-entregada',cEst.entregada);
  set('cnt-est-en_ruta',cEst.en_ruta);
  set('cnt-est-pendiente',cEst.pendiente);
  set('cnt-est-problema',cEst.problema);
  set('cnt-reg-SIERRA',cReg.SIERRA);
  set('cnt-reg-COSTA',cReg.COSTA);
  set('cnt-acc-Terrestre',cAcc.Terrestre);
  set('cnt-acc-Fluvial',cAcc.Fluvial);
  set('cnt-acc-Aérea',cAcc['Aérea']);
  set('cnt-zin-Urbana',cZin.Urbana);
  set('cnt-zin-Rural',cZin.Rural);
}

/* Reconstruye marcadores: usa datos del Excel si existen, si no usa MAP_SCHOOLS estático */
function renderMapMarkers(){
  if(!_mapObj)return;
  Object.values(_layerGroups).forEach(g=>{try{_mapObj.removeLayer(g);}catch(e){}});
  _layerGroups={};

  if(SCHOOLS.length>0){
    /* MODO EXCEL: coloreado por estado */
    const coordMap={};
    MAP_SCHOOLS.forEach(s=>{coordMap[String(s.amie).trim().toUpperCase()]=s;});

    const {regs,accs,zins,ests}=getActiveFilters();
    // Mostrar el panel de filtro de estado
    const estGrp=document.getElementById('fil-estado-group');
    if(estGrp)estGrp.style.display='';

    const provGroups={};
    SCHOOLS.forEach(s=>{
      const ref=coordMap[String(s.amie||"").trim().toUpperCase()];
      // MAP_SCHOOLS coords → Excel UTM coords → Excel direct lat/lon
      const lat=(ref&&ref.lat)?ref.lat:(s.xlat||s.lat||null);
      const lon=(ref&&ref.lon)?ref.lon:(s.xlon||s.lon||null);
      if(!lat||!lon)return;
      const canton=s.canton||(ref&&ref.canton)||'';
      if(_activeCanton&&canton!==_activeCanton)return;
      const schoolReg=(ref&&ref.reg)||s.reg||'';
      if(regs.length&&schoolReg&&!regs.includes(schoolReg))return;
      const accVal=s.acceso||(ref&&ref.acc)||'Terrestre';
      if(accs.length&&!accs.includes(accVal))return;
      if(zins.length&&ref&&!zins.includes(ref.zona))return;
      const estadoVal=s.estado||'pendiente';
      if(ests.length&&!ests.includes(estadoVal))return;
      if(!provGroups[s.prov])provGroups[s.prov]=[];
      provGroups[s.prov].push({...s,lat,lon,
        name:(ref&&ref.name)||s.nombre||s.amie,
        canton,acc:accVal});
    });

    _activeProvinces=new Set(Object.keys(provGroups));
    buildMapLegend();

    Object.keys(provGroups).forEach(prov=>{
      const pColor=provColor(prov);
      const group=L.markerClusterGroup({
        iconCreateFunction:function(cluster){
          const children=cluster.getAllChildMarkers();
          let nE=0,nR=0,nP=0,nPr=0;
          children.forEach(m=>{const e=m._estadoKC||'pendiente';if(e==='entregada')nE++;else if(e==='en_ruta')nR++;else if(e==='problema')nPr++;else nP++;});
          const dom=nE>=nR&&nE>=nP&&nE>=nPr?'entregada':nR>=nP&&nR>=nPr?'en_ruta':nPr>=nP?'problema':'pendiente';
          const bg=ESTADO_COLORS[dom]||pColor;
          return L.divIcon({html:`<div style="background:${bg};color:#fff;border-radius:50%;width:36px;height:36px;display:flex;align-items:center;justify-content:center;font-size:11px;font-weight:700;box-shadow:0 2px 6px rgba(0,0,0,.35)">${cluster.getChildCount()}</div>`,className:'',iconSize:[36,36]});
        },showCoverageOnHover:false,maxClusterRadius:50
      });

      provGroups[prov].forEach(s=>{
        const color=ESTADO_COLORS[s.estado]||'#9AA4B8';
        const marker=L.circleMarker([s.lat,s.lon],{radius:7,fillColor:color,color:'#fff',weight:2,fillOpacity:0.92});
        marker._estadoKC=s.estado;
        marker._sicProv=prov;
        marker._sicCanton=s.canton;
        const badge=s.acc==='Aérea'?'✈️ Aérea':s.acc==='Fluvial'?'🛶 Fluvial':'🚗 Terrestre';
        const elbl=ESTADO_LABELS[s.estado]||s.estado;
        marker.bindPopup(`<div style="font-size:12px;min-width:210px"><div style="font-weight:800;color:#14213D;margin-bottom:6px;line-height:1.3">${esc(s.name)}</div><div style="color:#5C6478;font-size:11px;margin-bottom:2px">📍 ${esc(s.canton)}</div><div style="color:#5C6478;font-size:11px;margin-bottom:8px">${badge}</div><div><span style="background:${color};color:#fff;border-radius:4px;padding:2px 8px;font-size:11px;font-weight:700">${elbl}</span></div><div style="margin-top:6px;font-size:10px;color:#666">Día ${s.dia} · ${s.raciones.toLocaleString('es-EC')} raciones · ${(s.estudiantes||0).toLocaleString('es-EC')} estudiantes</div></div>`);
        group.addLayer(marker);
      });
      _layerGroups[prov]=group;
      _mapObj.addLayer(group);
    });
  } else {
    /* MODO ESTÁTICO: catálogo MAP_SCHOOLS sin datos de entrega */
    const estGrp2=document.getElementById('fil-estado-group');
    if(estGrp2)estGrp2.style.display='none';
    _activeProvinces=new Set(MAP_PROVINCES);
    MAP_PROVINCES.forEach(prov=>{
      const color=provColor(prov);
      const group=L.markerClusterGroup({
        iconCreateFunction:function(cluster){
          return L.divIcon({html:`<div style="background:${color};color:#fff;border-radius:50%;width:34px;height:34px;display:flex;align-items:center;justify-content:center;font-size:11px;font-weight:700;box-shadow:0 2px 6px rgba(0,0,0,.3)">${cluster.getChildCount()}</div>`,className:'',iconSize:[34,34]});
        },showCoverageOnHover:false,maxClusterRadius:50
      });
      const {regs:fr,accs:fa,zins:fz}=getActiveFilters();
      let staticFiltered=MAP_SCHOOLS.filter(s=>s.prov===prov);
      if(_activeCanton)staticFiltered=staticFiltered.filter(s=>s.canton===_activeCanton);
      if(fr.length)staticFiltered=staticFiltered.filter(s=>fr.includes(s.reg));
      if(fa.length)staticFiltered=staticFiltered.filter(s=>fa.includes(s.acc));
      if(fz.length)staticFiltered=staticFiltered.filter(s=>fz.includes(s.zona));
      staticFiltered.forEach(s=>{
        const marker=L.circleMarker([s.lat,s.lon],{radius:6,fillColor:color,color:'#fff',weight:1.5,fillOpacity:0.85});
        const badge=s.acc==='Aérea'?'✈️ Aérea':s.acc==='Fluvial'?'🛶 Fluvial':'🚗 Terrestre';
        marker.bindPopup(`<div style="font-size:12px;min-width:200px"><div style="font-weight:800;color:#14213D;margin-bottom:6px;line-height:1.3">${s.name}</div><div style="color:#5C6478;font-size:11px;margin-bottom:4px">📍 ${s.canton} · Dist. ${s.parr}</div><div style="color:#5C6478;font-size:11px;margin-bottom:4px">${badge}</div></div>`);
        marker._sicProv=prov; marker._sicCanton=s.canton;
        group.addLayer(marker);
      });
      _layerGroups[prov]=group;
      _mapObj.addLayer(group);
    });
    buildMapLegend();
  }
  updateMapCantonesSelect();
  updateMapCount();
  updateFilterCounts();
}

/* buildMapLegendEstado removed — counts now in filter panel */

function buildMapLegend(){
  const el=document.getElementById('map-legend');
  if(!el)return;
  const counts={};
  const provs=SCHOOLS.length>0
    ? [...new Set(SCHOOLS.map(s=>s.prov).filter(Boolean))].sort()
    : MAP_PROVINCES;
  if(SCHOOLS.length>0){
    SCHOOLS.forEach(s=>{if(s.prov)counts[s.prov]=(counts[s.prov]||0)+1;});
  } else {
    MAP_PROVINCES.forEach(p=>counts[p]=MAP_SCHOOLS.filter(s=>s.prov===p).length);
  }
  el.innerHTML=provs.map(prov=>`
    <div class="map-legend-item" onclick="toggleMapProvince('${prov}')">
      <input type="checkbox" id="chk-${prov}" checked onchange="toggleMapProvince('${prov}')" onclick="event.stopPropagation()">
      <span class="swatch" style="background:${provColor(prov)}"></span>
      <span class="map-legend-label">${prov.charAt(0)+prov.slice(1).toLowerCase()}</span>
      <span class="map-legend-count" style="font-size:10px;color:var(--gray-400);margin-left:auto">${counts[prov]||0}</span>
    </div>`).join('');
}

function toggleMapProvince(prov){
  const chk=document.getElementById('chk-'+prov);
  if(!chk)return;
  // Sync checkbox if clicked from label
  if(document.activeElement!==chk) chk.checked=!chk.checked;
  if(chk.checked){
    _activeProvinces.add(prov);
    _mapObj.addLayer(_layerGroups[prov]);
  }else{
    _activeProvinces.delete(prov);
    _mapObj.removeLayer(_layerGroups[prov]);
  }
  updateMapCantonesSelect();
  updateMapCount();
}

function updateMapCantonesSelect(){
  const sel=document.getElementById('cantones-select');
  if(!sel)return;
  const prev=sel.value;
  const cantons=[...new Set(
    [..._activeProvinces].flatMap(p=>MAP_CANTONES[p]||[])
  )].sort();
  sel.innerHTML='<option value="">Todos los cantones</option>'+
    cantons.map(c=>`<option value="${c}">${c.charAt(0)+c.slice(1).toLowerCase()}</option>`).join('');
  if(cantons.includes(prev)) sel.value=prev;
  else { sel.value=''; _activeCanton=''; }
}

function applyMapFilters(){
  const sel=document.getElementById('cantones-select');
  _activeCanton=sel?sel.value:'';
  renderMapMarkers();
}


function getActiveFilters(){
  const regs=[], accs=[], zins=[], ests=[];
  ['SIERRA','COSTA'].forEach(v=>{const el=document.getElementById('fil-reg-'+v); if(el&&el.checked)regs.push(v);});
  ['Terrestre','Fluvial','Aérea'].forEach(v=>{const el=document.getElementById('fil-acc-'+v); if(el&&el.checked)accs.push(v);});
  ['Urbana','Rural'].forEach(v=>{const el=document.getElementById('fil-zin-'+v); if(el&&el.checked)zins.push(v);});
  ['entregada','en_ruta','pendiente','problema'].forEach(v=>{const el=document.getElementById('fil-est-'+v); if(el&&el.checked)ests.push(v);});
  return {regs,accs,zins,ests};
}

function applyMapFiltersFull(){
  if(!_mapObj)return;
  const sel=document.getElementById('cantones-select');
  _activeCanton=sel?sel.value:'';
  renderMapMarkers();
}

function applyMapFiltersRebuild(){
  if(!_mapObj)return;
  renderMapMarkers();
}

function resetMapFilters(){
  _activeProvinces=new Set(MAP_PROVINCES);
  _activeCanton='';
  ['SIERRA','COSTA'].forEach(v=>{const el=document.getElementById('fil-reg-'+v);if(el)el.checked=true;});
  ['Terrestre','Fluvial','Aérea'].forEach(v=>{const el=document.getElementById('fil-acc-'+v);if(el)el.checked=true;});
  ['Urbana','Rural'].forEach(v=>{const el=document.getElementById('fil-zin-'+v);if(el)el.checked=true;});
  ['entregada','en_ruta','pendiente','problema'].forEach(v=>{const el=document.getElementById('fil-est-'+v);if(el)el.checked=true;});
  MAP_PROVINCES.forEach(p=>{const chk=document.getElementById('chk-'+p);if(chk)chk.checked=true;});
  renderMapMarkers();
}

function updateMapCount(){
  const el=document.getElementById('map-count-bar');
  if(!el)return;
  // Count the markers actually visible (sum all layers)
  let count=0;
  Object.values(_layerGroups).forEach(g=>{
    try{count+=g.getLayers().length;}catch(e){}
  });
  el.textContent=count.toLocaleString('es-EC')+' instituciones';
}